from __future__ import annotations
from dataclasses import dataclass, field
from .ruling_citation import house_ruling
NAOCL_AS_COMPOUND_RULING_ID = 'HOUSE-NAOCL-AS-COMPOUND-20260913'
PHOSPHORUS_RATIO_RULING_ID = 'HOUSE-PHOSPHORUS-DOSE-RATIO-20260916'
_MW = {'Fe': 55.845, 'Cl': 35.453, 'H': 1.008, 'Na': 22.99, 'O': 15.999, 'Ca': 40.078, 'C': 12.011, 'S': 32.06, 'N': 14.007, 'P': 30.974, 'Al': 26.982}
_MW['OH'] = _MW['O'] + _MW['H']
_MW['OCl'] = _MW['O'] + _MW['Cl']
_MW['CO3'] = _MW['C'] + 3 * _MW['O']
_MW['S2O5'] = 2 * _MW['S'] + 5 * _MW['O']
_MW['HSO3'] = _MW['H'] + _MW['S'] + 3 * _MW['O']
_MW['HPO4'] = _MW['H'] + _MW['P'] + 4 * _MW['O']
_MW['PO4'] = _MW['P'] + 4 * _MW['O']
_MW['NH4'] = _MW['N'] + 4 * _MW['H']
_MW['organic_polymer'] = 1.0
_MW['organic_antiscalant'] = 1.0
_MW['K'] = 39.098
_MW['HCO3'] = _MW['H'] + _MW['C'] + 3 * _MW['O']
_MW['urea'] = _MW['C'] + _MW['O'] + 2 * (_MW['N'] + 2 * _MW['H'])
_MW['trace_elements'] = 1.0

@dataclass(frozen=True)
class ReagentGrade:
    """One commercial grade, as bought.

    ``strength_w_w`` is the active compound's mass fraction of the product as
    delivered -- for a solution the balance is carrier water, for a solid the
    balance is inert. ``stoichiometry`` gives the active compound's own formula
    as species and their counts, which is what makes the split checkable rather
    than typed.
    """
    reagent_id: str
    commercial_name: str
    active_compound: str
    strength_w_w: float
    density_kg_m3: float
    physical_form: str
    stoichiometry: dict[str, int]
    provenance: str = '[ASSUMED]'
    basis_note: str = ''
    reported_as: str = ''
    remainder_composition: dict[str, float] = field(default_factory=dict)

    def active_mw(self) -> float:
        return sum((_MW[species] * count for species, count in self.stoichiometry.items()))

def _grade(**kwargs) -> ReagentGrade:
    return ReagentGrade(**kwargs)
